     1	// «Монетка»: игрок выбирает сторону, один бросок в start определяет исход и закрывает раунд.
     2	// Спецификация: games/coin/spec.md. Решения: decisions/coin.md (D-001…D-006).
     3	import type { GameModule, Rng, Step } from '../../../platform/sdk/types.ts';
     4	import { GameError } from '../../../platform/sdk/types.ts';
     5	
     6	/** Сторона монеты. */
     7	export type Side = 'heads' | 'tails';
     8	
     9	/** Нормализованные параметры раунда. */
    10	export interface CoinParams {
    11	  side: Side;
    12	}
    13	
    14	/** Состояние раунда: выбранная сторона, выпавшая сторона и признак выигрыша. */
    15	export interface CoinState {
    16	  side: Side;
    17	  outcome: Side;
    18	  win: boolean;
    19	}
    20	
    21	/** Коэффициент выплаты при угадывании: честные 2 минус 2 % house edge (D-001). */
    22	export const PAYOUT_MULTIPLIER = 1.96;
    23	
    24	function isSide(value: unknown): value is Side {
    25	  return value === 'heads' || value === 'tails';
    26	}
    27	
    28	/** Исход по одному числу rng: r < 0.5 → heads, иначе tails (D-002). */
    29	function flip(rng: Rng): Side {
    30	  return rng.next() < 0.5 ? 'heads' : 'tails';
    31	}
    32	
    33	/**
    34	 * Серверный модуль «Монетки».
    35	 * Тип `P` оставлен по умолчанию (как у заготовки): платформа отдаёт в `start` результат `validateParams`,
    36	 * а `start` ещё раз нормализует параметры до обращения к rng.
    37	 */
    38	const game: GameModule = {
    39	  id: 'coin',
    40	
    41	  validateParams(params: unknown): CoinParams {
    42	    if (typeof params !== 'object' || params === null || Array.isArray(params)) {
    43	      throw new GameError('INVALID_PARAMS', 'Параметры должны быть объектом { side }');
    44	    }
    45	    const side = (params as { side?: unknown }).side;
    46	    if (!isSide(side)) {
    47	      throw new GameError('INVALID_PARAMS', 'side должен быть "heads" или "tails"');
    48	    }
    49	    return { side };
    50	  },
    51	
    52	  start({ bet, params, rng }: { bet: number; params: CoinParams; rng: Rng }): Step<CoinState> {
    53	    // Всё, что может упасть, — до обращения к rng (контракт platform/sdk/types.ts).
    54	    const { side } = game.validateParams(params);
    55	    const outcome = flip(rng);
    56	    const win = outcome === side;
    57	    return {
    58	      status: 'finished',
    59	      state: { side, outcome, win },
    60	      payout: win ? bet * PAYOUT_MULTIPLIER : 0,
    61	    };
    62	  },
    63	
    64	  action(): Step<CoinState> {
    65	    throw new GameError('INVALID_ACTION', 'Раунд «Монетки» состоит из одного броска');
    66	  },
    67	
    68	  publicView(state: CoinState): { side: Side; outcome: Side; win: boolean } {
    69	    return { side: state.side, outcome: state.outcome, win: state.win };
    70	  },
    71	};
    72	
    73	export default game;
